// Gather data from all three GitHub API responses
const commits = $('Fetch Commits').first().json.body || $('Fetch Commits').first().json || [];
const issues = $('Fetch Closed Issues').first().json.body || $('Fetch Closed Issues').first().json || [];
const prs = $('Fetch Merged PRs').first().json.body || $('Fetch Merged PRs').first().json || [];

const oneWeekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

// Process commits
const commitList = (Array.isArray(commits) ? commits : []).map(c => ({
  sha: (c.sha || '').substring(0, 7),
  message: (c.commit?.message || '').split('\n')[0],
  author: c.commit?.author?.name || c.author?.login || 'unknown',
  date: c.commit?.author?.date || ''
}));

// Process closed issues (filter out PRs)
const issueList = (Array.isArray(issues) ? issues : [])
  .filter(i => !i.pull_request)
  .map(i => ({
    number: i.number,
    title: i.title,
    closed_by: i.user?.login || 'unknown',
    labels: (i.labels || []).map(l => l.name).join(', ')
  }));

// Process merged PRs (only those merged in the last week)
const prList = (Array.isArray(prs) ? prs : [])
  .filter(p => p.merged_at && new Date(p.merged_at) >= oneWeekAgo)
  .map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login || 'unknown',
    merged_at: p.merged_at
  }));

// Get config from the Set Config node
const config = $('Set Config').first().json;

return [{
  json: {
    repo: `${config.repo_owner}/${config.repo_name}`,
    language: config.language || 'EN',
    commits: commitList,
    closed_issues: issueList,
    merged_prs: prList,
    commit_count: commitList.length,
    issue_count: issueList.length,
    pr_count: prList.length,
    period_start: oneWeekAgo.toISOString().split('T')[0],
    period_end: new Date().toISOString().split('T')[0]
  }
}];

