const response = $input.first().json;
const body = response.body || response;
const content = body.content || [];
const summaryText = content.map(c => c.text || '').join('\n') || 'No summary generated.';

const config = $('Set Config').first().json;
const data = $('Aggregate Data').first().json;

return [{
  json: {
    summary: summaryText,
    repo: data.repo,
    period: `${data.period_start} → ${data.period_end}`,
    stats: {
      commits: data.commit_count,
      issues_closed: data.issue_count,
      prs_merged: data.pr_count
    },
    webhook_url: config.webhook_url
  }
}];

